 const[pubTipOpen,setPubTipOpen]=React.useState(false);const[pubTipAmount,setPubTipAmount]=React.useState("50");const[pubTipBusy,setPubTipBusy]=React.useState(false);const[pubSubMsg,setPubSubMsg]=React.useState("");
