 async function openCommunity(id:string){const r=await api(`/api/communities/${id}`);if(r.ok){const x=await r.json();if(x.data){setSelectedCommunity(x.data);setCommunityId(id);if(x.data.ownerId===profile?.id||x.data.memberRole==="OWNER"||x.data.memberRole==="MODERATOR"){void api(`/api/communities/${id}/members`).then(a=>a.ok?a.json():null).then(m=>{if(m)setCommunityMembers(Array.isArray(m?.data)?m.data:(m?.data?.items??[]))}).catch(()=>undefined)}else setCommunityMembers([])}}}
 async function toggleCommunity(c:Community){const endpoint=c.joined?`/api/communities/${c.id}/leave`:`/api/communities/${c.id}/join`;const r=await api(endpoint,{method:"POST"});if(r.ok){setCommunities(v=>v.map(x=>x.id===c.id?{...x,joined:!c.joined,_count:{...x._count,members:Math.max(0,x._count.members+(c.joined?-1:1))}}:x))}}
