 async function toggleEventRsvp(e:EventItem){const r=e.rsvpStatus?await api(`/api/events/${e.id}/rsvp`,{method:"DELETE"}):await api(`/api/events/${e.id}/rsvp`,{method:"POST",body:JSON.stringify({status:"GOING"})});if(r.ok){setEvents(v=>v.map(x=>x.id===e.id?{...x,rsvpStatus:x.rsvpStatus?null:"GOING",_count:{...x._count,rsvps:Math.max(0,x._count.rsvps+(x.rsvpStatus?-1:1))}}:x))}}
 async function createEvent(){if(!newEvent.title.trim()||!newEvent.description.trim()||!newEvent.startsAt)return;const r=await api("/api/events",{method:"POST",body:JSON.stringify(newEvent)});if(r.ok){const x=await r.json();setEvents(v=>[x.data,...v]);setShowEventCreate(false);setNewEvent({title:"",description:"",category:"ማህበረሰብ",location:"",startsAt:"",endsAt:"",isOnline:false,meetingText:""})}}
 async function votePoll(p:Poll,optionId:string){const selected=p.multiple?[...new Set([...p.votedOptionIds,optionId])]:[optionId];const r=await api(`/api/polls/${p.id}/vote`,{method:"POST",body:JSON.stringify({optionIds:selected})});if(r.ok){const x=await r.json();setPolls(v=>v.map(item=>item.id===p.id?x.data:item))}}
 async function createPoll(){const options=newPoll.options.map(x=>x.trim()).filter(Boolean);if(!newPoll.question.trim()||options.length<2)return;const r=await api("/api/polls",{method:"POST",body:JSON.stringify({...newPoll,options})});if(r.ok){const x=await r.json();setPolls(v=>[x.data,...v]);setShowPollCreate(false);setNewPoll({question:"",description:"",options:["",""],multiple:false,closesAt:""})}}
